#!/usr/bin/env bash
# GSZ step118 — detailed reseller-bot order alert. The website now sends a
# fully-detailed, preformatted message (+ all fields incl. type) to /api/notify.
# Safe + idempotent; restores on failure.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step118-$TS"; TMP=$(mktemp -d)
F=routes/checkout.js
echo "==> step118: detailed reseller-bot order alert"
mkdir -p "$BK/$(dirname "$F")"; cp "$GSZ/$F" "$BK/$F"; echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; cp "$BK/$F" "$GSZ/$F"; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo "==> applying"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/$F"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
[ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step118 OK ✅  reseller-bot order alerts now include title, order #, product, plan, version, customer WhatsApp, payment method, amount & status (preformatted message + all fields)."
